const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.spark}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const worlds=[
{id:'rover',title:'Rover Run',genre:'PATHFINDING',type:'puzzle',color:'#c6f879',description:'A tiny explorer. A dangerous grid. Your route home.',skill:'Sequencing & precision',lesson:'Plan a clear sequence, watch it execute, and revise the instruction where it goes wrong.',example:'east 2, north 1, west 1',controls:'Write a route using directions and distances. The rover executes every step literally.'},
{id:'catch',title:'Prism Catch',genre:'ARCADE',type:'action',color:'#78dedc',description:'Catch the signal. Let the noise fall. Keep moving.',skill:'Inclusion & exclusion',lesson:'Be specific about what to include and exclude. Your rules determine what the collector acts on.',example:'collect cyan circles; ignore coral squares',controls:'Steer with ← → or drag the collector. Apply a rule to choose which falling shapes it accepts.'},
{id:'bridge',title:'Bridgeworks',genre:'CONSTRUCTION',type:'puzzle',color:'#e9bc84',description:'Mind the gap. Build a crossing that can carry you.',skill:'Constraints & resources',lesson:'Account for the world’s constraints. A plan must work within the load, materials, and budget.',example:'place wood at 1; place steel at 3',controls:'Place beams with material and slot instructions, then send the rover across your construction.'},
{id:'garden',title:'Drone Garden',genre:'SIMULATION',type:'action',color:'#bfa2ef',description:'A restless swarm. Find a little order in the chaos.',skill:'Context & boundaries',lesson:'A destination alone can be insufficient. Add environmental constraints and the spacing the task needs.',example:'gather at 300 220; avoid hazards; spread 35',controls:'Set a gathering point, avoidance, and spacing. Watch the swarm respond and adjust the instruction.'},
{id:'laser',title:'Laser Loom',genre:'LIGHT PUZZLE',type:'puzzle',color:'#f0cb73',description:'Bend a beam. Bring a sleeping reactor back to life.',skill:'Iteration & feedback',lesson:'Change a specific part of your plan and observe its effect. Small revisions are easier to diagnose.',example:'rotate A clockwise',controls:'Rotate mirrors by clicking them or writing commands. Fire the laser to trace the resulting path.'},
{id:'factory',title:'Factory Flow',genre:'AUTOMATION',type:'puzzle',color:'#80c9f1',description:'Write the rules. Ship the cargo. Keep the line alive.',skill:'Conditions & priority',lesson:'Rules run in order. Put specific exceptions before general instructions so the right rule wins.',example:'if red -> dock A; otherwise -> recycle',controls:'Write routing rules and run a batch. Watch each cargo item follow the first rule it matches.'},
{id:'defense',title:'Signal Defense',genre:'TOWER DEFENSE',type:'action',color:'#f0918a',description:'Program your defenses. Outlast the incoming waves.',skill:'Strategy & tradeoffs',lesson:'Choose the behavior that fits the goal. Range, speed, and target priorities change the outcome.',example:'target fastest; range 170',controls:'Build on the circular sockets. Give your towers a targeting rule, then launch the wave.'},
{id:'escape',title:'Escape Protocol',genre:'ESCAPE ROOM',type:'puzzle',color:'#9ec9b4',description:'Read the room. Follow the evidence. Find your way out.',skill:'Grounding & evidence',lesson:'Use information you can actually observe. Inspect the environment before deciding on the next action.',example:'inspect desk',controls:'Inspect objects, collect useful items, and act on the clues you find. The room remembers your actions.'}
];
function art(id,hero=false){let content='';const grid=`<path d="M0 35h300M0 70h300M0 105h300M0 140h300M35 0v180M70 0v180M105 0v180M140 0v180M175 0v180M210 0v180M245 0v180M280 0v180" stroke="#83aeb5" stroke-opacity=".08" stroke-width=".6"/>`;
if(id==='rover'){content=`<g transform="translate(73 25) rotate(-10 80 65)">${Array.from({length:30},(_,i)=>{const x=i%6*26,y=Math.floor(i/6)*26;return `<rect x="${x}" y="${y}" width="22" height="22" rx="3" fill="${[8,9,16,18,20,23].includes(i)?'#435e5b':'#243f3d'}" stroke="#5a8270" stroke-opacity=".45"/>`;}).join('')}<path d="M11 115h52V63h52V11h26" fill="none" stroke="#c6f879" stroke-width="3" stroke-dasharray="5 4"/><rect x="3" y="106" width="18" height="18" rx="5" fill="#c6f879"/><rect x="7" y="112" width="11" height="5" rx="2" fill="#264e3b"/><path d="m64 54 6 8-6 8-6-8Z" fill="#c6f879"/><rect x="132" y="3" width="18" height="18" rx="5" fill="#235b63" stroke="#7cdee4"/></g>`;}
if(id==='catch'){content=`${Array.from({length:10},(_,i)=>{const x=42+i*21,y=25+(i*37)%105;const col=['#7edce0','#f1c47b','#ec8d86'][i%3];return i%3===0?`<circle cx="${x}" cy="${y}" r="8" fill="${col}"/><path d="M${x} ${y-13}v-13" stroke="${col}" opacity=".25"/>`:`<rect x="${x-6}" y="${y-6}" width="12" height="12" rx="2" transform="rotate(${i%3===1?45:0} ${x} ${y})" fill="${col}" opacity="${i%3===2?.35:1}"/>`;}).join('')}<path d="M28 140h244" stroke="#74aeb6" stroke-dasharray="3 5" opacity=".3"/><rect x="115" y="146" width="70" height="8" rx="4" fill="#c6f879"/><path d="m116 142 6-13m62 13-6-13" stroke="#c6f879" stroke-width="2"/>`;}
if(id==='bridge'){content='<path d="M0 116h61l9 64H0ZM239 116h61v64h-70Z" fill="#3c4d4b"/><path d="M61 113h178" stroke="#d8b783" stroke-width="6"/><path d="m62 116 28 36 29-36 30 36 30-36 30 36 29-36M90 116v35m59-35v35m60-35v35" fill="none" stroke="#988d73" stroke-width="2"/><rect x="39" y="96" width="21" height="15" rx="4" fill="#c6f879"/><circle cx="44" cy="113" r="4" fill="#9abf78"/><circle cx="55" cy="113" r="4" fill="#9abf78"/><path d="M250 114V68m0 0 21 9-21 8" stroke="#81d1d7" stroke-width="2" fill="#81d1d733"/><path d="M70 168q80-20 160 0" fill="none" stroke="#365a6a" stroke-width="8"/>';}
if(id==='garden'){content='<circle cx="207" cy="92" r="51" fill="#bfa2ef0d" stroke="#bfa2ef" stroke-dasharray="4 5" stroke-opacity=".6"/><circle cx="110" cy="93" r="22" fill="#ef92871f" stroke="#ef9287" stroke-opacity=".4"/>'+Array.from({length:8},(_,i)=>{let x=i<4?43+i*25:180+(i%2)*40,y=i<4?40+(i%2)*88:72+Math.floor((i-4)/2)*39;return `<path d="m${x} ${y-6} 8 12-8-3-8 3Z" fill="#c6f879"/><path d="M${x-4} ${y+12}l-6 8" stroke="#c6f879" opacity=".18"/>`;}).join('');}
if(id==='laser'){content='<path d="M24 125h64V49h112v76h65" stroke="#f0cb73" stroke-width="3" fill="none"/><path d="M24 125h64V49h112v76h65" stroke="#f0cb73" stroke-opacity=".13" stroke-width="13" fill="none"/>'+[[88,125],[88,49],[200,49],[200,125]].map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="13" fill="#263e43" stroke="#597b81"/><path d="M${x-9} ${y+(i%2===0?9:-9)}l18 ${i%2===0?-18:18}" stroke="#b1d4dc" stroke-width="3"/>`).join('')+'<rect x="16" y="117" width="15" height="16" rx="3" fill="#f0cb73"/><circle cx="270" cy="125" r="12" fill="#4b5734" stroke="#c6f879"/><path d="m144 79 13 8v16l-13 8-13-8V87Z" fill="#4c5c63"/>';}
if(id==='factory'){content='<path d="M0 93h150l44-43h106M150 93l44 43h106" fill="none" stroke="#314b55" stroke-width="24"/><path d="M0 93h150l44-43h106M150 93l44 43h106" fill="none" stroke="#668691" stroke-width="1" stroke-dasharray="4 6"/><rect x="33" y="83" width="20" height="20" rx="4" fill="#ed9391"/><rect x="84" y="83" width="20" height="20" rx="4" fill="#85caea"/><rect x="201" y="40" width="20" height="20" rx="4" fill="#ed9391"/><rect x="220" y="126" width="20" height="20" rx="4" fill="#85caea"/><rect x="135" y="79" width="28" height="28" rx="7" fill="#26393d" stroke="#c6f879"/><text x="149" y="98" text-anchor="middle" font-size="14" font-family="monospace" fill="#c6f879">?</text><text x="278" y="30" font-family="monospace" font-size="9" fill="#ed9391">A</text><text x="278" y="166" font-family="monospace" font-size="9" fill="#85caea">B</text>';}
if(id==='defense'){content='<path d="M0 50h85v85h120V62h95" fill="none" stroke="#33484f" stroke-width="24"/><path d="M0 50h85v85h120V62h95" fill="none" stroke="#667c80" stroke-width="1" stroke-dasharray="4 5"/>'+[[48,95],[144,83],[242,117]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="38" fill="#f0918a08" stroke="#f0918a" stroke-opacity=".2"/><circle cx="${x}" cy="${y}" r="11" fill="#49564d" stroke="#b4cba9"/><path d="M${x} ${y}v-16" stroke="#c6f879" stroke-width="5"/>`).join('')+'<path d="m145 83 32 51" stroke="#c6f879" stroke-width="2"/><circle cx="177" cy="134" r="6" fill="#ec918c"/><circle cx="84" cy="104" r="6" fill="#7edce0"/><circle cx="60" cy="50" r="6" fill="#ec918c"/><path d="m280 44 13 8v20l-13 8-13-8V52Z" fill="#364b3e" stroke="#c6f879"/>';}
if(id==='escape'){content='<path d="M51 30h198v123H51Z" fill="#1d3438" stroke="#4c676c" stroke-width="5"/><path d="M51 153h198" stroke="#2b4849" stroke-width="12"/><rect x="72" y="51" width="55" height="27" rx="3" fill="#657363"/><rect x="80" y="48" width="20" height="12" rx="2" fill="#a4b7a0"/><rect x="177" y="53" width="47" height="44" rx="4" fill="#3e535b" stroke="#78959b"/><circle cx="200" cy="75" r="10" fill="#2d434c" stroke="#9bb6b9"/><path d="M200 68v14m-7-7h14" stroke="#9bb6b9"/><rect x="135" y="112" width="31" height="41" fill="#1b292e" stroke="#9dc7ad"/><rect x="142" y="120" width="17" height="7" rx="2" fill="#c6f879" opacity=".6"/><circle cx="115" cy="113" r="8" fill="#c6f879"/>';}
return `<svg viewBox="0 0 300 180" aria-hidden="true"><defs><radialGradient id="art-${id}-${hero?'hero':'card'}"><stop stop-color="${worlds.find(w=>w.id===id)?.color||'#c6f879'}" stop-opacity=".1"/><stop offset="1" stop-color="#12222a" stop-opacity="0"/></radialGradient></defs><rect width="300" height="180" fill="#12222a"/>${grid}<ellipse cx="150" cy="90" rx="150" ry="100" fill="url(#art-${id}-${hero?'hero':'card'})"/>${content}</svg>`;}
const tiers=[{name:'Explorer',roman:'I',description:'Learn the systems',color:'#c6f879'},{name:'Operator',roman:'II',description:'Adapt your strategy',color:'#7edce0'},{name:'Architect',roman:'III',description:'Master the constraints',color:'#c3a8ef'}];
const transfers={rover:'Break a larger request into ordered steps. Identify the failed step before rewriting the whole plan.',catch:'Tell an AI exactly what information to include and exclude. Test the rule on borderline examples.',bridge:'Include the budget, available resources, and hard requirements in the brief. Check whether the proposed plan satisfies them together.',garden:'Describe the environment as well as the destination. Make boundaries, hazards, and acceptable outcomes explicit.',laser:'Change one instruction at a time and compare the result. A targeted edit is easier to evaluate.',factory:'Write specific exceptions before broad rules, and test cases that match more than one condition.',defense:'State which goal has priority when requirements compete. Compare alternatives using the same criteria.',escape:'Use observed evidence, flag missing information, and satisfy dependencies before taking the next action.'};
let progressStorage;try{progressStorage=localStorage;}catch{progressStorage={getItem(){throw Error('Unavailable');},setItem(){throw Error('Unavailable');}};}
const {state,persistent:storageOK}=window.PromptProgress.read(progressStorage);let persistent=storageOK;
const main=document.querySelector('main'),victory=document.querySelector('#victory');
let currentPage='arcade',filter='all',activeWorld=null,activeStage=0,disposeGame=null,mountToken=0,audioContext=null,session=null,focusMode=false,journalFilter='all',removedNote=null;
const missionKey=(id,stage)=>`${id}:${stage}`;
const totalStars=()=>Object.values(state.results).reduce((sum,r)=>sum+r.stars,0);
const cleared=()=>Object.keys(state.results).length;
const mastered=()=>Object.values(state.results).filter(r=>r.stars===3).length;
const best=(id,stage)=>state.results[missionKey(id,stage)];
const nextStage=id=>{const i=tiers.findIndex((_,s)=>!best(id,s));return i<0?2:i;};
const rank=()=>cleared()===24?'World architect':cleared()>=16?'Systems master':cleared()>=8?'Signal voyager':cleared()>=3?'Prompt pilot':'Curious explorer';
function save(){try{progressStorage.setItem(window.PromptProgress.key,JSON.stringify(state));}catch{persistent=false;toast('Browser storage is full or unavailable. Progress lasts for this session.');}}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),3200);}
function sfx(kind='move'){if(!state.sound)return;try{audioContext=audioContext||new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();const frequencies=kind==='win'?[440,554,659,880]:kind==='hit'?[130,85]:[440];frequencies.forEach((f,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain(),t=audioContext.currentTime+i*.1;o.type=kind==='hit'?'triangle':'sine';o.frequency.value=f;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.045,t+.01);g.gain.exponentialRampToValueAtTime(.0001,t+.16);o.connect(g);g.connect(audioContext.destination);o.start(t);o.stop(t+.17);});}catch{}}
function starMarkup(stars){return Array.from({length:3},(_,i)=>`<span class="${i<stars?'earned':''}">★</span>`).join('');}
function updateProfile(){document.querySelector('#rank-title').textContent=rank();document.querySelector('#worlds-count').textContent=`${cleared()} / 24 missions cleared`;document.querySelector('#stars-count').textContent=`${totalStars()} ★`;document.querySelector('#header-stars').textContent=totalStars();document.querySelector('#progress-bar').style.width=cleared()/24*100+'%';const sound=document.querySelector('#sound-toggle');sound.setAttribute('aria-pressed',String(state.sound));sound.innerHTML=`${icon('sound')}<span>Sound ${state.sound?'on':'off'}</span>`;}
function heading(title,sub,extra=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${extra}</div>`;}
function achievementData(){return[{name:'First contact',sub:'Clear your first mission',yes:cleared()>0,symbol:'↗'},{name:'Constellation',sub:'Earn 12 stars',yes:totalStars()>=12,symbol:'✦'},{name:'World traveler',sub:'Clear a mission in every world',yes:worlds.every(w=>tiers.some((_,s)=>best(w.id,s))),symbol:'◎'},{name:'Systems operator',sub:'Clear all Operator missions',yes:worlds.every(w=>best(w.id,1)),symbol:'⌘'},{name:'Architect',sub:'Clear all Architect missions',yes:worlds.every(w=>best(w.id,2)),symbol:'◇'},{name:'Perfect expedition',sub:'Collect all 72 stars',yes:totalStars()===72,symbol:'✳'}];}
function worldCard(w,index){const completed=tiers.filter((_,s)=>best(w.id,s)).length;return `<article class="world-card advanced-world" style="--accent:${w.color}"><button class="world-cover cover-button" data-game="${w.id}" data-stage="${nextStage(w.id)}" aria-label="Play ${w.title}"><span class="world-number">WORLD ${String(index+1).padStart(2,'0')}</span>${art(w.id)}<span class="world-genre">${w.genre}</span></button><div class="world-info"><div class="world-title-row"><h3>${w.title}</h3><span>${completed}/3</span></div><p>${w.description}</p><div class="stage-mini" aria-label="${w.title} stages">${tiers.map((tier,s)=>`<button data-game="${w.id}" data-stage="${s}" class="${best(w.id,s)?'cleared':''}" aria-label="Play ${w.title}, ${tier.name}, ${best(w.id,s)?.stars||0} stars"><span>${tier.roman}</span><span class="mini-stars">${starMarkup(best(w.id,s)?.stars||0)}</span></button>`).join('')}</div><button class="world-enter" data-game="${w.id}" data-stage="${nextStage(w.id)}">${completed?'Continue expedition':'Enter world'} ${icon('arrow')}</button></div></article>`;}
function renderArcade(){const [resumeId,resumeStage]=state.last?state.last.split(':'):['rover','0'];const today=new Date(),day=Math.floor(Date.UTC(today.getFullYear(),today.getMonth(),today.getDate())/86400000),daily=worlds[day%8],dailyStage=Math.floor(day/8)%3;
main.innerHTML=heading('Your next level starts here.','Deeper worlds. Smarter instructions. Bigger possibilities.',`<span class="edition-chip">EXPEDITION <b>03</b></span>`)+`<section class="hero advanced-hero"><div class="hero-copy"><div class="eyebrow">${icon('spark')} THE ADVANCED EXPEDITION</div><h2>Command the<br><em>impossible.</em></h2><p>Eight worlds to explore. Three stages to master.<br>Build a plan, watch it unfold, and make your next move count.</p><div class="hero-actions"><button class="primary-btn" data-game="${resumeId}" data-stage="${resumeStage}">${state.last?'Resume expedition':'Start your expedition'} ${icon('arrow')}</button><span class="hero-meta">24 MISSIONS<br>72 STARS TO EARN</span></div></div><div class="hero-scene">${art('rover',true)}<span class="scene-caption"><i></i> YOUR IDEAS, IN MOTION</span><div class="scene-command"><span>›</span><span>repeat 3 { east 2; north 2 }</span><span>EXECUTE ↗</span></div></div><div class="hero-bottom"><span><i></i> EVERY WORLD IS OPEN</span><span>EXPERIMENT → EXECUTE → EVOLVE</span></div></section><div class="expedition-strip"><div><span class="strip-icon">◈</span><div><small>YOUR EXPEDITION</small><strong>${cleared()} <span>/ 24 missions</span></strong></div></div><div><span class="strip-icon cyan">✦</span><div><small>STARS COLLECTED</small><strong>${totalStars()} <span>/ 72 stars</span></strong></div></div><button data-game="${daily.id}" data-stage="${dailyStage}"><span class="strip-icon violet">↗</span><div><small>TODAY’S PICK · ${tiers[dailyStage].name.toUpperCase()}</small><strong>${daily.title}</strong></div>${icon('arrow')}</button></div><section aria-labelledby="world-title"><div class="section-heading"><div><h2 id="world-title">Choose your world</h2><p>Explorer → Operator → Architect. Every stage changes the challenge.</p></div><button class="quiet-link" data-page="guide">Field guide ${icon('arrow')}</button></div><div class="filters" role="group" aria-label="Filter worlds">${[['all','All worlds'],['puzzle','Puzzle & strategy'],['action','Action & simulation']].map(([id,title])=>`<button data-filter="${id}" class="filter ${filter===id?'active':''}" aria-pressed="${filter===id}">${title}</button>`).join('')}<span class="filter-note">Free retries. Your best run counts.</span></div><div class="world-grid">${worlds.map((w,i)=>({w,i})).filter(({w})=>filter==='all'||w.type===filter).map(({w,i})=>worldCard(w,i)).join('')}</div></section><section class="expedition-note">${icon('terminal')}<div><h3>Every attempt tells you something.</h3><p>Your run journal captures commands, feedback, and breakthroughs. Return to a good idea whenever you need it.</p></div><button class="secondary-btn" data-page="journal">Open run journal ${icon('arrow')}</button></section>`;}
function renderProgress(){main.innerHTML=heading('An expedition worth remembering.','Your best results across 24 missions. Keep exploring at your own pace.',`<button class="secondary-btn" id="export-progress">Export progress ↓</button>`)+`<div class="stats-grid"><div class="stat-card"><span>MISSIONS CLEARED</span><div class="stat-value">${cleared()} <span style="font-size:19px;color:#86a496">/ 24</span></div><small>Eight worlds, three stages each.</small></div><div class="stat-card"><span>STARS COLLECTED</span><div class="stat-value">${totalStars()} <span style="font-size:19px;color:#86a496">/ 72</span></div><small>${mastered()} missions mastered with three stars.</small></div><div class="stat-card"><span>YOUR RANK</span><div class="stat-value" style="font-size:24px">${rank()}</div><small>Progress comes from what you make happen.</small></div></div><div class="section-heading"><h2>Your milestones</h2><span class="world-count">${achievementData().filter(x=>x.yes).length} / 6 EARNED</span></div><div class="achievement-grid">${achievementData().map(a=>`<article class="achievement ${a.yes?'earned':''}"><span>${a.symbol}</span><strong>${a.name}</strong><small>${a.sub}</small><i>${a.yes?'✓ Earned':'In progress'}</i></article>`).join('')}</div><div class="section-heading" style="margin-top:30px"><h2>The mission atlas</h2></div><div class="atlas"><div class="atlas-row atlas-header"><span>WORLD</span>${tiers.map(t=>`<span>${t.name.toUpperCase()}</span>`).join('')}</div>${worlds.map(w=>`<div class="atlas-row"><strong style="color:${w.color}">${w.title}<small>${w.skill}</small></strong>${tiers.map((tier,s)=>`<button data-game="${w.id}" data-stage="${s}" aria-label="Play ${w.title} ${tier.name}"><span class="mini-stars">${starMarkup(best(w.id,s)?.stars||0)}</span><small>${best(w.id,s)?best(w.id,s).score.toLocaleString()+' pts':'Explore ↗'}</small></button>`).join('')}</div>`).join('')}</div><p class="privacy-note">${persistent?'Progress, commands, and notes are saved in this browser.':'Browser storage is unavailable; progress lasts for this session.'} Your earlier eight-world progress is carried into Explorer stages. Export a backup whenever you like.</p><label class="import-progress">Restore an exported backup <input id="import-progress" type="file" accept="application/json,.json"></label>`;}
function journalRows(entries){return entries.map((e,i)=>{const [id,s]=e.key.split(':'),w=worlds.find(x=>x.id===id);return `<article class="journal-entry"><div class="journal-icon ${e.type}">${{run:'›',error:'!',hint:'?',milestone:'◇',complete:'✓'}[e.type]}</div><div><div class="journal-entry-top"><strong>${w.title}</strong><span>${tiers[Number(s)].name}</span><time>${formatTime(e.at)}</time></div><p>${esc(e.message)}</p>${e.command?`<pre>${esc(e.command)}</pre><button class="quiet-link" data-restore-event="${state.journal.indexOf(e)}">Load this command ↗</button>`:''}</div></article>`;}).join('');}
function formatTime(value){const d=new Date(value);return Number.isNaN(d.getTime())?'':d.toLocaleString(undefined,{timeZone:'Europe/Berlin',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});}
function renderJournal(){const filtered=state.journal.filter(e=>journalFilter==='all'||e.type===journalFilter);main.innerHTML=heading('Good ideas deserve a second run.','Review your attempts, keep useful commands, and see what changed.')+`<div class="journal-layout"><section><div class="section-heading"><h2>Run journal</h2><span class="world-count">LAST 100 EVENTS</span></div><div class="filters">${[['all','Everything'],['run','Commands'],['error','Feedback'],['complete','Completions']].map(([id,t])=>`<button data-journal-filter="${id}" class="filter ${journalFilter===id?'active':''}">${t}</button>`).join('')}</div><div class="journal-list">${filtered.length?journalRows(filtered):'<div class="empty-state"><span>⌘</span><h3>Your next experiment starts here.</h3><p>Play a mission to capture the commands you run and what happens next.</p><button class="secondary-btn" data-page="arcade">Explore worlds ↗</button></div>'}</div></section><aside class="notebook-panel"><div class="eyebrow">YOUR TOOLKIT</div><h2>Command notebook</h2>${removedNote?'<div class="undo-note" role="status">Command removed. <button id="undo-note">Undo</button></div>':''}<p>Save a command from any mission. Load it into the same stage when you want to experiment again.</p>${state.notebook.length?state.notebook.map((n,i)=>{const [id,s]=n.key.split(':');return `<article class="notebook-entry"><strong>${worlds.find(w=>w.id===id).title}<small>${tiers[Number(s)].name}</small></strong><pre>${esc(n.command)}</pre><div class="notebook-actions"><button class="quiet-link" data-load-note="${i}">Open in mission ↗</button><button class="remove-note" data-remove-note="${i}" aria-label="Remove this saved command">Remove</button></div></article>`;}).join(''):'<div class="empty-notebook">Your saved commands will appear here.<br>Look for “Save command” below a game.</div>'}</aside></div>`;}
function renderGuide(){main.innerHTML=heading('From a good idea to a working plan.','A field guide for every stage of your expedition.')+`<div class="learning-loop"><span><b>01</b> Observe the goal</span><i>→</i><span><b>02</b> Write a plan</span><i>→</i><span><b>03</b> Watch it run</span><i>→</i><span><b>04</b> Refine one thing</span></div><div class="tier-guide">${tiers.map((t,s)=>`<div><span style="color:${t.color}">${t.roman}</span><h3>${t.name}</h3><p>${['Discover the core mechanic. Read the objective and experiment with the commands.','New conditions change the answer. Reuse what you know, then adapt the plan.','Handle interacting constraints. Inspect feedback, optimize, and explain why the plan works.'][s]}</p></div>`).join('')}</div><div class="guide-grid">${worlds.map((w,i)=>`<article class="guide-card" style="--accent:${w.color}"><div class="eyebrow">0${i+1} / ${w.skill.toUpperCase()}</div><h3>${w.title}</h3><p>${w.controls}</p><code>${esc(w.id==='rover'?'repeat 2 { east 1; north 1 }':w.example)}</code><p>${transfers[w.id]}</p><button class="quiet-link" data-game="${w.id}" data-stage="${nextStage(w.id)}">Enter the world ${icon('arrow')}</button></article>`).join('')}</div><p class="privacy-note">These games use documented commands and local simulations. Real AI accepts more flexible language and can produce uncertain or incorrect results. Transfer the habits: define the goal, supply relevant context, test examples, and verify the output.</p>`;}
function stopGame(){mountToken++;if(disposeGame){disposeGame();disposeGame=null;}activeWorld=null;session=null;if(victory.open)victory.close();}
function navigate(page,focus=true){stopGame();setFocus(false);currentPage=['arcade','progress','guide','journal'].includes(page)?page:'arcade';if(location.hash!==`#${currentPage}`)history.replaceState(null,'',`#${currentPage}`);document.querySelectorAll('.nav-item').forEach(b=>{b.classList.toggle('active',b.dataset.page===currentPage);if(b.dataset.page===currentPage)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});document.querySelector('#breadcrumb').textContent={arcade:'World select',progress:'Your expedition',guide:'Field guide',journal:'Run journal'}[currentPage];({arcade:renderArcade,progress:renderProgress,guide:renderGuide,journal:renderJournal})[currentPage]();if(focus){main.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}}
function addEvent(event){if(!activeWorld||!session||!['run','error','hint','milestone','complete'].includes(event.type))return;const message=String(event.message||'').slice(0,600);const command=typeof event.command==='string'?event.command.slice(0,8000):'';const entry={key:missionKey(activeWorld.id,activeStage),type:event.type,message,command,at:new Date().toISOString()};state.journal.unshift(entry);state.journal=state.journal.slice(0,100);const editor=document.querySelector('#game-root textarea');if(editor)state.drafts[entry.key]=editor.value.slice(0,8000);if(event.type==='run'){session.runs++;session.completed=false;}if(event.type==='error')session.errors++;if(event.type==='hint')session.hints++;save();renderLiveJournal();}
function renderLiveJournal(){const root=document.querySelector('#live-journal');if(!root||!activeWorld)return;const key=missionKey(activeWorld.id,activeStage),events=state.journal.filter(e=>e.key===key).slice(0,4);root.innerHTML=events.length?events.map(e=>`<div class="live-event ${e.type}"><span>${{run:'›',error:'!',hint:'?',milestone:'◇',complete:'✓'}[e.type]}</span><p>${esc(e.message)}</p></div>`).join(''):'<p class="live-empty">Your commands and their outcomes will appear here as you play.</p>';const count=document.querySelector('#session-count');if(count)count.textContent=`${session.runs} runs · ${session.errors} feedback events`;}
function playWorld(id,stage=0,restoreCommand){const w=worlds.find(w=>w.id===id);if(!w)return;stage=Math.max(0,Math.min(2,Number.isInteger(Number(stage))?Number(stage):0));stopGame();activeWorld=w;activeStage=stage;const token=mountToken,key=missionKey(id,stage),restoredDraft=restoreCommand??state.drafts[missionKey(id,stage)];session={runs:0,errors:0,hints:0,started:Date.now(),completed:false};state.last=key;save();currentPage='game';history.replaceState(null,'',`#play/${w.id}/${stage+1}`);document.querySelectorAll('.nav-item').forEach(b=>{b.classList.toggle('active',b.dataset.page==='arcade');b.removeAttribute('aria-current');});document.querySelector('#breadcrumb').textContent=`${w.title} · ${tiers[stage].name}`;const index=worlds.indexOf(w);
main.innerHTML=`<div class="game-page-heading" style="--accent:${w.color}"><button class="back-link" data-page="arcade">${icon('arrow')}World select</button><div class="game-title-area"><div class="eyebrow">WORLD ${String(index+1).padStart(2,'0')} / ${w.genre}</div><h1>${w.title}</h1></div><button id="focus-toggle" class="focus-button" aria-pressed="${focusMode}">${focusMode?'Exit focus':'Focus mode'} ⛶</button></div><div class="mission-toolbar"><div class="stage-tabs" role="group" aria-label="Mission stage">${tiers.map((tier,s)=>`<button data-game="${w.id}" data-stage="${s}" class="${stage===s?'active':''}" style="--tier:${tier.color}" aria-pressed="${stage===s}"><span>${tier.roman}</span>${tier.name}<i>${best(w.id,s)?'✓':''}</i></button>`).join('')}</div><div class="mission-personal-best"><span class="mini-stars">${starMarkup(best(id,stage)?.stars||0)}</span><span>${best(id,stage)?'PERSONAL BEST':'NEW FRONTIER'}</span></div></div><section id="game-root" class="game-root" aria-label="${w.title} ${tiers[stage].name} game"></section><div class="command-workbench"><div><span class="draft-dot"></span><span id="draft-status">Commands saved in this browser</span></div><div><button id="save-command">Save command ＋</button><button id="copy-command">Copy ⧉</button><button id="restart-mission">Restart mission ↻</button><button id="game-sound">Sound ${state.sound?'on':'off'} ♫</button></div></div><div class="mission-bottom"><section class="session-panel"><div class="session-top"><div><span class="eyebrow">LIVE RUN JOURNAL</span><h3>Watch. Understand. Refine.</h3></div><span id="session-count">0 runs · 0 feedback events</span></div><div id="live-journal" aria-live="polite"></div><button class="quiet-link" data-page="journal">View all attempts ${icon('arrow')}</button></section><aside class="transfer-panel"><span class="eyebrow">THE SKILL BEHIND THE GAME</span><h3>${w.skill}</h3><p>${transfers[id]}</p><label for="mission-note">What changed in your strategy?</label><textarea id="mission-note" maxlength="1200" placeholder="Keep a thought for your next attempt…">${esc(state.notes[key]||'')}</textarea><small>Your note saves automatically.</small></aside></div>`;
const mount=window.PromptGames?.[id];if(typeof mount!=='function'){document.querySelector('#game-root').innerHTML='<div class="panel"><h2>This world couldn’t load.</h2><p>Reload the page to try again.</p></div>';return;}
disposeGame=mount({root:document.querySelector('#game-root'),sfx,stage,onEvent:event=>{if(token===mountToken)addEvent(event);},onComplete:result=>{if(token!==mountToken||activeWorld?.id!==id||session?.completed)return;finishWorld(w,result);}});
const command=document.querySelector('#game-root textarea');if(command){command.maxLength=8000;const draft=restoredDraft;if(typeof draft==='string'){command.value=draft;state.drafts[key]=draft;save();document.querySelector('#draft-status').textContent='Draft restored · run it to apply';}}
renderLiveJournal();main.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function finishWorld(w,result){session.completed=true;const key=missionKey(w.id,activeStage),stars=Math.max(1,Math.min(3,Math.round(Number(result.stars)||1))),score=Number.isFinite(Number(result.score))?Math.max(0,Math.round(Number(result.score))):0;const beforeBadges=achievementData().filter(a=>a.yes).map(a=>a.name);window.PromptProgress.record(state,key,result);addEvent({type:'complete',message:`${tiers[activeStage].name} cleared with ${stars} stars and ${score.toLocaleString()} points.`});save();updateProfile();sfx('win');const newBadge=achievementData().find(a=>a.yes&&!beforeBadges.includes(a.name));const next=activeStage<2?{world:w,stage:activeStage+1}:{world:worlds[(worlds.indexOf(w)+1)%8],stage:0};const metrics=Object.entries(result.metrics||{}).filter(([k,v])=>k.length<80&&['number','string'].includes(typeof v)).slice(0,4);
document.querySelector('#victory-content').innerHTML=`<button class="dialog-close" data-dismiss aria-label="Return to the game">×</button><div class="victory-body"><div class="eyebrow">${esc(w.title.toUpperCase())} / ${tiers[activeStage].name.toUpperCase()} CLEARED</div><div class="victory-stars" aria-label="${stars} of 3 stars">${starMarkup(stars)}</div><h2 id="victory-title" tabindex="-1">You made it happen.</h2><p>${score.toLocaleString()} points · Best result saved</p>${newBadge?`<div class="badge-unlock">${newBadge.symbol} MILESTONE EARNED <strong>${newBadge.name}</strong></div>`:''}${metrics.length?`<div class="debrief-metrics">${metrics.map(([k,v])=>`<div><strong>${esc(String(v))}</strong><span>${esc(k)}</span></div>`).join('')}</div>`:''}<div class="victory-lesson">${esc(result.lesson||w.lesson)}</div><div class="victory-actions"><button class="secondary-btn" data-game="${w.id}" data-stage="${activeStage}">Refine & replay ↻</button><button class="primary-btn" ${cleared()===24?'data-page="progress"':`data-game="${next.world.id}" data-stage="${next.stage}"`}>${cleared()===24?'My expedition':activeStage<2?'Next stage':'Next world'} ${icon('arrow')}</button></div><button class="victory-plain" data-page="arcade">Back to world select</button></div>`;if(!victory.open)victory.showModal();document.querySelector('#victory-title').focus();}
function setFocus(on){focusMode=on;document.body.classList.toggle('focus-mode',on);const b=document.querySelector('#focus-toggle');if(b){b.textContent=on?'Exit focus ⛶':'Focus mode ⛶';b.setAttribute('aria-pressed',String(on));}}
function toggleSound(){state.sound=!state.sound;save();updateProfile();const b=document.querySelector('#game-sound');if(b)b.textContent=`Sound ${state.sound?'on':'off'} ♫`;if(state.sound)sfx('move');toast(`Game sound ${state.sound?'on':'off'}.`);}
function activeCommand(){return document.querySelector('#game-root textarea')?.value.trim()||'';}
function saveCommand(){const command=activeCommand();if(!command||!activeWorld){toast('Write a command first.');return;}const key=missionKey(activeWorld.id,activeStage);if(state.notebook.some(x=>x.key===key&&x.command===command)){toast('This command is already in your notebook.');return;}if(state.notebook.length>=30){toast('Your notebook holds 30 commands. Remove an entry in the run journal to make space.');return;}state.notebook.unshift({key,command,id:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7),at:new Date().toISOString()});save();toast('Command saved to your notebook.');}
async function copyCommand(){const command=activeCommand();if(!command){toast('Write a command first.');return;}try{await navigator.clipboard.writeText(command);toast('Command copied.');}catch{toast('Copy is unavailable. Select and copy the text in the command editor.');}}
function exportProgress(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='prompt-arcade-expedition.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your expedition backup is ready.');}
async function importProgress(file){if(!file)return;if(file.size>1500000){toast('Choose an expedition backup smaller than 1.5 MB.');return;}try{const raw=JSON.parse(await file.text());if(raw.version!==3||!raw.results||typeof raw.results!=='object')throw Error();const incoming=window.PromptProgress.clean(raw);for(const [k,r] of Object.entries(incoming.results)){const old=state.results[k];state.results[k]={...r,stars:Math.max(old?.stars||0,r.stars),score:Math.max(old?.score||0,r.score),runs:Math.max(old?.runs||0,r.runs)};}for(const [k,v] of Object.entries(incoming.drafts))if(!Object.prototype.hasOwnProperty.call(state.drafts,k))state.drafts[k]=v;for(const [k,v] of Object.entries(incoming.notes))if(!Object.prototype.hasOwnProperty.call(state.notes,k))state.notes[k]=v;for(const entry of incoming.notebook)if(state.notebook.length<30&&!state.notebook.some(x=>x.key===entry.key&&x.command===entry.command))state.notebook.push(entry);const seen=new Set(state.journal.map(e=>JSON.stringify(e)));state.journal=[...state.journal,...incoming.journal.filter(e=>!seen.has(JSON.stringify(e)))].sort((a,b)=>b.at.localeCompare(a.at)).slice(0,100);if(!state.last)state.last=incoming.last;save();updateProfile();renderProgress();toast('Backup merged. Your best results and current notes are kept.');}catch{toast('That file is not a valid Prompt Arcade expedition backup.');}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page){navigate(b.dataset.page);return;}if(b.dataset.game){playWorld(b.dataset.game,b.dataset.stage??0);return;}if(b.dataset.filter){filter=b.dataset.filter;renderArcade();main.querySelector(`[data-filter="${filter}"]`).focus({preventScroll:true});return;}if(b.dataset.journalFilter){journalFilter=b.dataset.journalFilter;renderJournal();return;}if(b.dataset.restoreEvent!==undefined){const entry=state.journal[Number(b.dataset.restoreEvent)];if(entry){const [id,s]=entry.key.split(':');playWorld(id,s,entry.command);}return;}if(b.dataset.removeNote!==undefined){const i=Number(b.dataset.removeNote);if(state.notebook[i]){removedNote={entry:state.notebook[i],index:i};state.notebook.splice(i,1);save();renderJournal();}return;}if(b.id==='undo-note'){if(removedNote){if(state.notebook.length>=30){toast('Remove an entry to make space for this command.');return;}if(!state.notebook.some(n=>n.key===removedNote.entry.key&&n.command===removedNote.entry.command))state.notebook.splice(removedNote.index,0,removedNote.entry);removedNote=null;save();renderJournal();}return;}if(b.dataset.loadNote!==undefined){const n=state.notebook[Number(b.dataset.loadNote)];if(n){const[id,s]=n.key.split(':');playWorld(id,s,n.command);}return;}if(b.id==='sound-toggle'||b.id==='game-sound'){toggleSound();return;}if(b.id==='focus-toggle'){setFocus(!focusMode);return;}if(b.id==='save-command'){saveCommand();return;}if(b.id==='copy-command'){copyCommand();return;}if(b.id==='export-progress'){exportProgress();return;}if(b.id==='restart-mission'&&activeWorld){playWorld(activeWorld.id,activeStage);return;}if(b.hasAttribute('data-dismiss')){victory.close();main.focus({preventScroll:true});}});
document.addEventListener('input',e=>{if(!activeWorld)return;const key=missionKey(activeWorld.id,activeStage);if(e.target.matches('#game-root textarea')){state.drafts[key]=e.target.value.slice(0,8000);save();const status=document.querySelector('#draft-status');if(status)status.textContent=persistent?'Draft saved · run to apply':'Draft kept for this session';}if(e.target.id==='mission-note'){state.notes[key]=e.target.value.slice(0,1200);save();}});
document.addEventListener('change',e=>{if(e.target.id==='import-progress')importProgress(e.target.files?.[0]);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&focusMode&&!victory.open){setFocus(false);return;}if(e.target.matches('input,textarea,select')||victory.open||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key.toLowerCase()==='m')toggleSound();if(e.key.toLowerCase()==='f'&&activeWorld)setFocus(!focusMode);});
victory.addEventListener('cancel',()=>setTimeout(()=>main.focus({preventScroll:true}),0));
function route(){const hash=location.hash.slice(1);if(hash.startsWith('play/')){const parts=hash.split('/');if(worlds.some(w=>w.id===parts[1])){playWorld(parts[1],parts[2]?Number(parts[2])-1:0);return;}}navigate(hash||'arcade',false);}
window.addEventListener('hashchange',route);window.addEventListener('pagehide',e=>{if(!e.persisted&&disposeGame)disposeGame();});document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));updateProfile();route();
